def count_distinct_substrings_length_k(s, k):
    if k <= 0 or k > len(s):
        return 0
    subs = sorted(s[i:i + k] for i in range(len(s) - k + 1))
    count = 0
    prev = None
    for sub in subs:
        if sub != prev:
            count += 1
            prev = sub
    return count

def swap_adjacent_pairs(s):
    n = len(s)
    pairs = [s[i:i + 2] for i in range(0, n, 2)]
    swapped = [p[::-1] if len(p) == 2 else p for p in pairs]
    return ''.join(swapped)

