def sort_strings_ignoring_case(words):
    import functools
    def compare(a, b):
        la, lb = a.lower(), b.lower()
        if la != lb:
            return -1 if la < lb else 1
        if a == b:
            return 0
        return -1 if a < b else 1
    return sorted(words, key=functools.cmp_to_key(compare))

def longest_substring_without_repeat(s):
    seen = set()
    left = 0
    best = ""
    for right, ch in enumerate(s):
        while ch in seen:
            seen.remove(s[left])
            left += 1
        seen.add(ch)
        if right - left + 1 > len(best):
            best = s[left:right + 1]
    return best

