def compress_repeated_chars(s):
    if not s:
        return ''
    i = 0
    n = len(s)
    parts = []
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        parts.append(s[i] + str(j - i))
        i = j
    return ''.join(parts)

