def nth_ugly_number(n):
    heap = [1]
    seen = {1}
    value = 1
    for _ in range(n):
        value = heapq.heappop(heap)
        for factor in (2, 3, 5):
            nxt = value * factor
            if nxt not in seen:
                seen.add(nxt)
                heapq.heappush(heap, nxt)
    return value

