def is_valid_binary_fraction(s):
    if '.' not in s:
        return False
    dot_count = s.count('.')
    if dot_count != 1:
        return False
    idx = s.index('.')
    int_part, frac_part = s[:idx], s[idx+1:]
    if not int_part or not frac_part:
        return False
    valid_chars = set('01')
    return set(int_part) <= valid_chars and set(frac_part) <= valid_chars

