def render_template_default(template, values, default):
    output = []
    buffer = []
    in_brace = False
    for ch in template:
        if ch == '{':
            in_brace = True
            buffer = []
        elif ch == '}' and in_brace:
            in_brace = False
            key = ''.join(buffer)
            output.append(str(values.get(key, default)))
        elif in_brace:
            buffer.append(ch)
        else:
            output.append(ch)
    return ''.join(output)

